export function find(db:DatabaseSync,tenantId:string,requestId:string) {
 return db.prepare('SELECT * FROM reservations WHERE request_id=? LIMIT 1').get(requestId) as {tenant_id:string;request_id:string;items_json:string;total_cents:number;fee_cents:number;status:string}|undefined;
}
